+static void counting_sort_pass(uint32_t* input, uint32_t* output, size_t n, int shift) {
+    // Use a temporary buffer for counting (max value 256 for 8 bits)
+    uint32_t counts[256] = {0};
+
+    // 1. Count frequencies using NEON for vectorized counting
+    size_t i = 0;
+    for (; i + 3 < n; i += 4) {
+        // Load 4 input elements
+        uint32_t val0 = input[i];
+        uint32_t val1 = input[i+1];
+        uint32_t val2 = input[i+2];
+        uint32_t val3 = input[i+3];
+
+        // Extract and count 4 keys (8 bits)
+        counts[val0 >> shift & 0xFF]++;
+        counts[val1 >> shift & 0xFF]++;
+        counts[val2 >> shift & 0xFF]++;
+        counts[val3 >> shift & 0xFF]++;
+    }
+    // Handle remainder elements sequentially
+    for (; i < n; ++i) {
+        uint32_t key = (input[i] >> shift) & 0xFF;
+        counts[key]++;
+    }
+
+    // 2. Calculate cumulative counts (prefix sums)
+    uint32_t start_pos[256] = {0};
+    uint32_t sum = 0;
+    for (int i = 0; i < 256; ++i) {
+        start_pos[i] = sum;
+        sum += counts[i];
+    }
+
+    // 3. Distribute elements to output
+    for (size_t i = 0; i < n; ++i) {
+        uint32_t key = (input[i] >> shift) & 0xFF;
+        output[start_pos[key]++] = input[i];
+    }
